// THE GEOMINGO FLAGS, one file each: data/flags/<CODE>.svg, made from data/flags.js by data/tools/build-flags.js (do not edit by hand).
// FLAGS[code] gives the address of the flag's image. The page shows at once without waiting for any flag; once it has loaded,
// all the flags come quietly in one download (data/flags.json), so a stamp shows its flag straight away (Héctor 2026-11-18).
const FLAGS={};
(()=>{const s=document.currentScript,base=(s&&s.src?s.src:location.href).replace(/[^/]*$/,'')+'flags/',V='f79b106cbe';
  for(const k of ["ABW","AFG","AGO","AIA","ALA","ALB","AND","ARE","ARG","ARM","ASM","ATF","ATG","AUS","AUT","AZE","BDI","BEL","BEN","BES","BFA","BGD","BGR","BHR","BHS","BIH","BLM","BLR","BLZ","BMU","BOL","BRA","BRB","BRN","BTN","BVT","BWA","CAF","CAN","CCK","CHE","CHL","CHN","CIV","CMR","COD","COG","COK","COL","COM","CPV","CRI","CUB","CUW","CXR","CYM","CYP","CZE","DEU","DJI","DMA","DNK","DOM","DZA","ECU","EGY","ERI","ESH","ESP","EST","ETH","FIN","FJI","FLK","FRA","FRO","FSM","GAB","GBR","GEO","GGY","GHA","GIB","GIN","GLP","GMB","GNB","GNQ","GRC","GRD","GRL","GTM","GUF","GUM","GUY","HKG","HMD","HND","HRV","HTI","HUN","IDN","IMN","IND","IOT","IRL","IRN","IRQ","ISL","ISR","ITA","JAM","JEY","JOR","JPN","KAZ","KEN","KGZ","KHM","KIR","KNA","KOR","KWT","LAO","LBN","LBR","LBY","LCA","LIE","LKA","LSO","LTU","LUX","LVA","MAC","MAF","MAR","MCO","MDA","MDG","MDV","MEX","MHL","MKD","MLI","MLT","MMR","MNE","MNG","MNP","MOZ","MRT","MSR","MTQ","MUS","MWI","MYS","MYT","NAM","NCL","NER","NFK","NGA","NIC","NIU","NLD","NOR","NPL","NRU","NZL","OMN","PAK","PAN","PCN","PER","PHL","PLW","PNG","POL","PRI","PRK","PRT","PRY","PSE","PYF","QAT","REU","ROU","RUS","RWA","SAU","SDN","SEN","SGP","SGS","SHN","SJM","SLB","SLE","SLV","SMR","SOM","SPM","SRB","SSD","STP","SUR","SVK","SVN","SWE","SWZ","SXM","SYC","SYR","TCA","TCD","TGO","THA","TJK","TKL","TKM","TLS","TON","TTO","TUN","TUR","TUV","TWN","TZA","UGA","UKR","UMI","UNK","URY","USA","UZB","VAT","VCT","VEN","VGB","VIR","VNM","VUT","WLF","WSM","YEM","ZAF","ZMB","ZWE"])FLAGS[k]=base+k+'.svg?v='+V;
  // then all the flags in one download (data/flags.json): from then on FLAGS[code] is the image itself, ready at once
  const warm=()=>fetch(base.slice(0,-6)+'flags.json?v='+V).then(r=>r.ok?r.json():null).then(J=>{if(!J)return;
    for(const k in J){let u;Object.defineProperty(FLAGS,k,{enumerable:true,configurable:true,get:()=>u||(u='data:image/svg+xml;utf8,'+encodeURIComponent(J[k]))})}}).catch(()=>{});
  if(document.readyState==='complete')setTimeout(warm,300);else addEventListener('load',()=>setTimeout(warm,300),{once:true})})();
